// Discord 알림(113) 본문 만들기. 웹훅 주소는 Discord 노드의 자격 증명에만 둔다.
// 11/09 반소람: 티켓 카드(embed)로 보낸다. 색 막대(차단 빨강·해제 초록·확인 필요 주황), IP·심각도·계정·티켓·상태 칸.
// 입력 필드는 원본과 같다(level, case_id, title, src_ip, ticket_id, result, detail, ctx).
const b = $input.first().json;
const x = b.ctx || {};
const CASE = { S1: ['로그인 무차별 대입', 'High'], S4: ['계정 탈취 의심', 'High'], S7: ['홈페이지 변조', 'Critical'],
  S8: ['포털 스캔·로그인 반복', 'Medium'], S10: ['경계 차단·스캔·로그인 반복', 'High'], S12: ['요청 폭주', 'High'],
  H1: ['민원 도배', 'Medium'] };
const ACT = { 'portal/block': '포털 IP 차단', 'pfsense/block': 'pfSense 차단', 'pfsense/fw_block': 'pfSense 차단',
  'portal/restrict_posting': '민원 작성 제한', 'portal/lock': '계정 잠금' };
const RES = { applied: '적용', already_applied: '이미 적용', released: '해제', dry_run: '시험(조치 없음)',
  failed: '실패', rejected: '거부', skipped: '건너뜀' };
const [name, severity] = CASE[b.case_id] || [b.title || '알림', '-'];
const release = /원복/.test(b.title || '');
const bad = b.level === 'error';
const steps = (x.results || []).map((s, i) => {
  if (release) return `${s.step === 1 ? 'pfSense 해제' : '포털 해제'} ${RES[s.result] || s.result}`;
  const e = (x.expected || [])[i] || {};
  return `${ACT[`${e.via}/${e.action}`] || `조치 ${i + 1}`} ${RES[s.result] || s.result}`;
});
const verb = bad ? '⛔ 확인 필요' : release ? '✅ 해제' : '🚫 차단';
const flow = release ? `승인 ${x.approver || '-'} → ${steps.join(' → ') || '해제 대상 없음'}`
  : `Graylog ${b.case_id || ''} 경보 → n8n 자동 대응 → ${steps.join(' · ') || '조치 없음'}`;
const fields = [{ name: 'IP', value: b.src_ip || '-', inline: true }, { name: '심각도', value: severity, inline: true }];
if (x.username) fields.push({ name: '계정', value: x.username, inline: true });
fields.push({ name: '티켓', value: b.ticket_id || '-', inline: true },
  { name: '상태', value: bad ? '사람 확인 필요' : release ? '원복 완료' : '차단 중 · 담당자 확인 후 해제', inline: true });
if (bad) fields.push({ name: '사유', value: String(b.detail || '-').slice(0, 300), inline: false });
const embed = { title: `${verb} · [${b.case_id || '-'}] ${name}`, description: flow,
  color: bad ? 0xE67E22 : release ? 0x2ECC71 : 0xE74C3C, fields,
  footer: { text: `해담 SOAR · n8n 실행 ${$execution.id} · 대시보드 http://127.0.0.1:8089` }, timestamp: new Date().toISOString() };
// content는 알림 미리보기(모바일 푸시)에 쓰이는 한 줄
return [{ json: { content: `${verb} [${b.case_id || '-'}] ${b.src_ip || ''} ${b.ticket_id || ''}`.trim(), embed, ctx: b.ctx } }];

// Discord 노드 결과(또는 자격 증명 없음·전송 실패)를 sent 여부로 정리
const j = $input.first().json;
const failed = !!(j.error || (j.message && /credential|webhook|ENOTFOUND|\b4\d\d\b/i.test(String(j.message))));
return [{ json: { sent: !failed, error: failed ? String((j.error && j.error.message) || j.message || j.error) : null, ctx: $('Discord 본문').first().json.ctx } }];
